int setsockopt_pppox_l2tp(struct socket *sock, int level, int optname,
                          char __user *optval, unsigned int optlen)
{
    int ret = 0;
    struct sock *sk = sock->sk;
    struct pppox_sock *po = pppox_sk(sk);
    struct pppol2tp_session *session;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (optlen < sizeof(u32))
        return -EINVAL;

    if (!sock->sk->sk_state)
        return -ENOTCONN;

    session = po->session;
    if (!session)
        return -ENOTCONN;

    switch (optname) {
    case PPCP_IPOPT_KEEPALIVE:
        {
            u32 val;
            if (copy_from_user(&val, optval, sizeof(val)))
                return -EFAULT;
            session->keepalive = val;
        }
        break;
    case PPCP_IPOPT_RECVSEQ:
        {
            u32 val;
            if (copy_from_user(&val, optval, sizeof(val)))
                return -EFAULT;
            session->recvseq = val;
        }
        break;
    case PPCP_IPOPT_SENDSEQ:
        {
            u32 val;
            if (copy_from_user(&val, optval, sizeof(val)))
                return -EFAULT;
            session->sendseq = val;
        }
        break;
    case PPCP_IPOPT_DEBUG:
        {
            u32 val;
            if (copy_from_user(&val, optval, sizeof(val)))
                return -EFAULT;
            session->debug = val;
        }
        break;
    default:
        ret = -EINVAL;
    }

    return ret;
}

int setsockopt_pppol2tp(struct socket *sock, int level, int optname, char __user *optval, unsigned int optlen) {
    int err = 0;
    struct sock *sk = sock->sk;
    struct pppol2tp_session *session;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (optlen < sizeof(int))
        return -EINVAL;

    if (!sock->sk->sk_state)
        return -ENOTCONN;

    session = pppol2tp_get_session(sk);
    if (!session)
        return -ENOENT;

    switch (optname) {
        case PPPOX_OPT_SESSION_ID:
            {
                int session_id;
                if (copy_from_user(&session_id, optval, sizeof(session_id)))
                    return -EFAULT;
                session->session_id = session_id;
            }
            break;
        case PPPOX_OPT_TUNNEL_ID:
            {
                int tunnel_id;
                if (copy_from_user(&tunnel_id, optval, sizeof(tunnel_id)))
                    return -EFAULT;
                session->tunnel_id = tunnel_id;
            }
            break;
        default:
            return -ENOPROTOOPT;
    }

    return err;
}

int pppol2tp_setsockopt(struct socket *sock, int level, int optname, char __user *optval, unsigned int optlen) {
    struct sock *sk = sock->sk;
    struct pppol2tp_session *session;
    void *value;
    int err = 0;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (optlen < sizeof(int))
        return -EINVAL;

    value = kmalloc(optlen, GFP_KERNEL);
    if (!value)
        return -ENOMEM;

    if (copy_from_user(value, optval, optlen)) {
        err = -EFAULT;
        goto out;
    }

    if (!sock->sk->sk_state) {
        err = -ENOTCONN;
        goto out;
    }

    session = pppol2tp_get_session(sock);
    if (!session) {
        err = -EINVAL;
        goto out;
    }

    if (session->session_id == 0) {
        /* Set tunnel options */
        err = pppol2tp_set_tunnel_options(session, optname, value, optlen);
    } else {
        /* Set session options */
        err = pppol2tp_set_session_options(session, optname, value, optlen);
    }

out:
    kfree(value);
    return err;
}

int pppol2tp_setsockopt(struct socket *sock, int level, int optname, char __user *optval, unsigned int optlen) {
    int err = 0;
    struct sock *sk = sock->sk;
    struct pppol2tp_socket *po = pppol2tp_sk(sk);

    if (level != SOL_PPPOL2TP) {
        return -EINVAL;
    }

    if (optlen < sizeof(u32)) {
        return -EINVAL;
    }

    u32 val;
    if (copy_from_user(&val, optval, sizeof(val))) {
        return -EFAULT;
    }

    if (!sock->sk->sk_state) {
        return -ENOTCONN;
    }

    if (optname == PPPOL2TP_SO_RECVSEQ || optname == PPPOL2TP_SO_SENDSEQ) {
        if (val) {
            po->flags |= (optname == PPPOL2TP_SO_RECVSEQ) ? PPOL2TP_F_RECVSEQ : PPOL2TP_F_SENDSEQ;
        } else {
            po->flags &= ~((optname == PPPOL2TP_SO_RECVSEQ) ? PPOL2TP_F_RECVSEQ : PPOL2TP_F_SENDSEQ);
        }
        return 0;
    }

    return -ENOPROTOOPT;
}

int pppol2tp_setsockopt(struct socket *sock, int level, int optname,
                        char __user *optval, unsigned int optlen)
{
    struct sock *sk = sock->sk;
    int err = 0;
    __u32 session_id;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (optlen < sizeof(__u32))
        return -EINVAL;

    if (copy_from_user(&session_id, optval, sizeof(__u32)))
        return -EFAULT;

    if (!sock->sk->sk_bound_dev_if)
        return -EINVAL;

    if (!session_id)
        return -EINVAL;

    switch (optname) {
    case PPPOX_OPT_TTL:
        if (optlen < sizeof(int))
            return -EINVAL;
        {
            int val;
            if (copy_from_user(&val, optval, sizeof(int)))
                return -EFAULT;
            if (val < 0)
                return -EINVAL;
            sk->sk_ttl = val;
        }
        break;
    case PPPOX_OPT_DEBUG:
        {
            int val;
            if (copy_from_user(&val, optval, sizeof(int)))
                return -EFAULT;
            sk->sk_debug = val;
        }
        break;
    default:
        return -ENOPROTOOPT;
    }

    return err;
}
